fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cell: i32 = 8;
    let p: i32 = t % 120;
    let tri: i32 = if p > 60 { 120 - p } else { p };
    let th: i32 = 16 + tri / 2;
    let mut y: i32 = 0;
    while y < h {
        let mut x: i32 = 0;
        while x < w {
            let band: i32 = ((x + y + t * 2) / th) & 1;
            let c: i32 = if band == 0 { 0xc0261f } else { 0xf2ede4 };
            host::display::fill_rect(x, y, cell, cell, c);
            x = x + cell;
        }
        y = y + cell;
    }
    host::display::present();
}
